-- Resources content for two project-screen changes (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema. Depends on 20261029130000. + Add source moved from the project header to the
-- Sources toolbar, and the Setup tab's "Where this project stands" module was removed as a duplicate of
-- the Notebook tab's overview strip.

select private.rc_release_guide(
  p_slug => 'sourcework-research',
  p_tool_key => 'transcription',
  p_title => 'Analyzing a source',
  p_summary => 'Analyze a source for the findings that add to what the project knows and a few clips worth hearing, and review them beside the transcript.',
  p_screen_keys => array['sourcework.setup', 'sourcework.source', 'sourcework.project'],
  p_sort_order => 19,
  p_version_note => 'The project standing left the Setup tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Analyze reads one source and tells you what in it matters: the few findings that add to what the project already knows, and a few passages that might work as audio. Everything it suggests waits for your decision, and nothing is quoted or used until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Analyze a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Sources tab, choose "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":". Each source is read on its own, up to three at a time. You can leave the page while it runs, as long as the browser tab stays open. A source that is still transcribing can be analyzed once it finishes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a source, choose "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Analyze again","marks":[{"type":"bold"}]},{"type":"text","text":" under the Data points panel."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A research question is not required. With one, the model looks for what bears on it; without one, it looks for what a reporter would need to know, check or cite. Questions on the Setup tab sharpen the result, and fewer, more specific questions work better than a list of topics."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What you get"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Findings","marks":[{"type":"bold"}]},{"type":"text","text":": a short paraphrase with the passages it rests on, who said it, and one line on why it matters. The model is shown what the project has already accepted, so it adds to, sharpens or contradicts it instead of repeating it. Often it will find little in a source that repeats the others, and that is the intended result."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clips to review","marks":[{"type":"bold"}]},{"type":"text","text":": a few passages that might work on the air, shown above the findings. Play one, trim it, then accept it into an ordinary excerpt or reject it. Often there are none."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pages consulted","marks":[{"type":"bold"}]},{"type":"text","text":": the model can search the web when it needs context to read a source, such as an unfamiliar place, term or claim. The pages it relied on are listed on the Setup tab, and a search never uses an interviewee’s name. They inform the model’s reading and never count as evidence."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Set up the project"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select Setup, at the right of the tabs. Where the project stands is the row of steps on the Notebook tab, above the sources, not repeated here."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add the questions you are trying to answer. The ⋮ beside a question moves it up or down, or archives it. Archived questions keep their findings and can be restored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dismiss a page that is wrong or irrelevant and the model stops being shown it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Say who the interviewer is"}]},{"type":"paragraph","content":[{"type":"text","text":"On a source, open the speakers menu and tick "},{"type":"text","text":"Interviewer","marks":[{"type":"bold"}]},{"type":"text","text":" beside the person asking the questions. What an interviewer says is not treated as a finding or a clip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review findings in the source"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a source from its project and switch the panel beside the transcript from Excerpts to Data points. Each finding is underlined in lime where it is in the transcript. A dashed card and dashed underline are suggestions you have not reviewed yet."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":" keeps it. "},{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" hides it, and the Rejected filter brings it back."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" rewords the claim and accepts it. The model’s own wording is kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Play","marks":[{"type":"bold"}]},{"type":"text","text":" listens to the passage, so you can check the paraphrase against what was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analyze again later: accepted and rejected findings and clips are kept, and only suggestions you have not reviewed are replaced."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A finding is a paraphrase. To use the speaker’s own words, accept a clip or make an excerpt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview audio and text are sent to an outside service to be read, as they are for transcription."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the Excerpts tab holds the switch, and the player stays docked at the bottom."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-project-overview',
  p_tool_key => 'transcription',
  p_title => 'A project at a glance',
  p_summary => 'See where a project stands, do the next step yourself or with AI, and find any source.',
  p_screen_keys => array['sourcework.project'],
  p_sort_order => 12,
  p_version_note => 'Add source moved to the Sources toolbar',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project opens on where it stands and what to do next. You can do every step yourself, ask AI to do any step, or hand it the rest."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The steps and the next step"}]},{"type":"paragraph","content":[{"type":"text","text":"The row of steps runs Sources, Analyze, Review, Synthesis, Piece. A finished step is a link back to its tab. Under it, one panel names the next step and gives you one button for it: "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" when sources are ready, "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" when findings and clips are waiting, then Open Synthesis and Start a piece. The steps only report and suggest. You can use any tab at any time."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tabs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" holds what you browse. Sources lists the project's sources, Data points lists the findings you have accepted or rejected, and Excerpts lists the excerpts made from them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" is where you decide on the findings and clips that Analyze suggested. The number beside it is how many are waiting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis, Pieces and Setup work as before."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Run the remaining steps with AI"}]},{"type":"paragraph","content":[{"type":"text","text":"The link under the button opens a dialog that runs the steps still to do, one after another, and hands control back where you choose: after Analyze, after Synthesis, after Outline, or after a first draft. It starts on Analyze, so the Review tab stays yours. Going past Analyze accepts every suggested finding and clip without your review, and the dialog says so before you start; they can be put back for review afterwards. Keep the page open while it runs. Stop after this step ends the run, and what finished is kept."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each source has a bar showing how far it has come: processed, analyzed, reviewed. The word under it says which step it is on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filter sources searches titles. Show narrows the list to sources not yet analyzed or that need attention, and Sort puts the newest first or sorts by title. The list shows 25 at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a row to open the source. A source that failed to process says why under its title. The ⋮ menu at the end of the row opens the source or removes it from this project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ Add source sits with the filters above the source list. The ⋮ menu at the top of the page edits the background or deletes the project, with a list of what goes and what stays."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hints that go away"}]},{"type":"paragraph","content":[{"type":"text","text":"Short how-to notes on some screens, such as how to select words into an excerpt, show a Got it button. Select it and that note stays hidden in this browser."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-31-sourcework-add-source-and-setup',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-31',
  p_title => 'Sourcework: Add source moves to the source list, and Setup loses its duplicate status',
  p_guide_slugs => array['sourcework-project-overview', 'sourcework-research'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two things on a project moved. + Add source now sits with the filters above the source list on the Notebook tab, so the top of the page holds only the project's title, background and ⋮ menu. The Setup tab no longer repeats where the project stands: the row of steps and the next-step panel on the Notebook tab are the one place for that, and Setup holds the research questions and background. On a phone, rows of two controls now share one line at half width each."}]}]}$body$
);
